+import { mkdir, readFile, writeFile } from 'node:fs/promises'
+import { dirname, resolve } from 'pathe'
+import type { DurationObservation } from './duration-smoothing'
+
+export type DurationHistory = Map<string, DurationObservation[]>
+
+function isObservation(value: unknown): value is DurationObservation {
+  return !!value
+    && typeof value === 'object'
+    && Number.isFinite((value as DurationObservation).duration)
+    && Number.isFinite((value as DurationObservation).recordedAt)
+}
+
+function observations(value: unknown): DurationObservation[] | null {
+  if (typeof value === 'number' && Number.isFinite(value)) {
+    return [{ duration: value, recordedAt: 0 }]
+  }
+  if (!value || typeof value !== 'object') {
+    return null
+  }
+  const entry = value as { duration?: unknown, recordedAt?: unknown, observations?: unknown }
+  if (Array.isArray(entry.observations)) {
+    return entry.observations.every(isObservation) ? entry.observations : null
+  }
+  return isObservation(entry) ? [{ duration: entry.duration, recordedAt: entry.recordedAt }] : null
+}
+
+export async function readDurationHistory(root: string, path: string, ttl: number): Promise<DurationHistory | null> {
+  try {
+    const contents = JSON.parse(await readFile(resolve(root, path), 'utf8'))
+    if (!contents || typeof contents !== 'object' || Array.isArray(contents)) {
+      return null
+    }
+    const cutoff = ttl > 0 ? Date.now() - ttl : -Infinity
+    const history: DurationHistory = new Map()
+    for (const [file, entry] of Object.entries(contents)) {
+      const values = observations(entry)
+      if (!values) {
+        return null
+      }
+      history.set(file, values.filter(value => value.recordedAt === 0 || value.recordedAt >= cutoff))
+    }
+    return history
+  }
+  catch {
+    return null
+  }
+}
+
+export async function writeDurationHistory(root: string, path: string, history: DurationHistory, maxRuns: number): Promise<void> {
+  const data: Record<string, unknown> = {}
+  for (const [file, entries] of history) {
+    const values = [...entries].sort((a, b) => b.recordedAt - a.recordedAt).slice(0, maxRuns)
+    if (values.length) {
+      data[file] = maxRuns === 1 ? values[0] : { observations: values }
+    }
+  }
+  const destination = resolve(root, path)
+  await mkdir(dirname(destination), { recursive: true })
+  await writeFile(destination, `${JSON.stringify(data, null, 2)}\
`)
+}
