+import pm from 'picomatch'
+
+export interface ShardAffinityRule {
+  pattern: string
+  shardIndex: number
+}
+
+export function findAffinityShard(path: string, rules: ShardAffinityRule[], count: number): number | undefined {
+  const rule = rules.find(rule => pm.isMatch(path, rule.pattern))
+  return rule ? Math.min(rule.shardIndex, count - 1) : undefined
+}
