+    if (!contents || typeof contents !== 'object' || Array.isArray(contents)) {
+      return null
+    }
+    const cutoff = ttl > 0 ? Date.now() - ttl : -Infinity
+    const history: DurationHistory = new Map()
+    for (const [file, entry] of Object.entries(contents)) {
