  private async recordFileDurations(): Promise<void> {
    const sequence = this.config.sequence
    if (!sequence.recordFileDurations) {
      return
    }
    const history = await readDurationHistory(this.config.root, sequence.durationHistoryPath, sequence.durationHistoryTTL) || new Map()
    const recordedAt = Date.now()
    for (const file of this.state.getFiles()) {
      if (file.result) {
        const path = slash(relative(this.config.root, file.filepath))
        const entries = history.get(path) || []
        entries.push({ duration: Math.round(file.result.duration), recordedAt })
        history.set(path, entries)
      }
    }
    await writeDurationHistory(this.config.root, sequence.durationHistoryPath, history, sequence.durationHistoryMaxRuns)
  }

